def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num: int):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci(n: int):
        if n <= 0:
            return "Input should be positive integer"
        elif n == 1:
            return 0
        elif n == 2:
            return 1
        else:
            fib_list = [0, 1]
            while n >= 2:
                fib_list.append(fib_list[-1] + fib_list[-2])
                n -= 1
            return fib_list[-1]

    prime_fib_list = []
    num = 1
    while len(prime_fib_list) < n:
        fib_num = fibonacci(num)
        if is_prime(fib_num):
            prime_fib_list.append(fib_num)
        num += 1
    return prime_fib_list[-1]

